        row.type = skillConfig.type;
        row.keyName = skillConfig.keyName;
        row.ShowName = skillConfig.ShowName;
        row.SkillPoint = skillConfig.SkillPoint.ToString();

        switch (skillConfig.stateType)
        {
            case stateType.GR:
                row.attackType = "GR";
                break;
            case stateType.GI:
                row.attackType = "GI";
                break;
            case stateType.GM:
                row.attackType = "GM";
                break;
            case stateType.CT:
                row.attackType = "CT";
                break;
            case stateType.NONE:
                row.attackType = "NONE";
                break;
        }

        if (skillConfig.ai_trigger_ranges.Contains(behaviorEnterRange.inner_range))
            row.AI_close = "TRUE";
        else
            row.AI_close = "FALSE";
        if (skillConfig.ai_trigger_ranges.Contains(behaviorEnterRange.mid_range))
            row.AI_near = "TRUE";
        else
            row.AI_near = "FALSE";
        if (skillConfig.ai_trigger_ranges.Contains(behaviorEnterRange.far_range))
            row.AI_far = "TRUE";
        else
            row.AI_far = "FALSE";
        if (skillConfig.ai_trigger_ranges.Contains(behaviorEnterRange.out_of_range))
            row.AI_out = "TRUE";
        else
            row.AI_out = "FALSE";

        switch (skillConfig.SPLevel)
        {
            case EX.normal:
                row.SPLevel = "normal";
                break;
            case EX.EX1:
                row.SPLevel = "EX1";
                break;
            case EX.EX2:
                row.SPLevel = "EX2";
                break;
            case EX.EX3:
                row.SPLevel = "EX3";
                break;
            default:
                row.SPLevel = "NULL";
                break;
        }

        switch (skillConfig.canAirTrigger)
        {
            case true:
                row.canAirTrigger = "TRUE";
                break;
            case false:
                row.canAirTrigger = "FALSE";
                break;
        }

        switch (skillConfig.skillEmergentLevel)
        {
            case skillEmergentLevel.level1:
                row.skillEmergentLevel = "1";
                break;
            case skillEmergentLevel.level2:
                row.skillEmergentLevel = "2";
                break;
            case skillEmergentLevel.level3:
                row.skillEmergentLevel = "3";
                break;
            case skillEmergentLevel.none:
                row.skillEmergentLevel = "0";
                break;
        }

        row.rarelevel = skillConfig.rarelevel.ToString();

        return row;
