            case "EX3":
                _SkillConfig.SPLevel = EX.EX3;
                break;
            default:
                _SkillConfig.SPLevel = EX.NULL;
                break;
        }

        switch (row.canAirTrigger)
        {
            case "TRUE":
                _SkillConfig.canAirTrigger = true;
                break;
            case "FALSE":
                _SkillConfig.canAirTrigger = false;
                break;
        }

        switch(row.skillEmergentLevel)
